import { AsyncLocalStorage } from "node:async_hooks";

/**
 * Application-owned response security headers.
 *
 * The CSP is generated by the application (not nginx) because the SSR hydration
 * script must carry a per-request nonce; a static edge policy would have to
 * allow `'unsafe-inline'` scripts. nginx keeps the transport-level headers
 * (HSTS, X-Frame-Options, nosniff, Referrer-Policy, Permissions-Policy) and must
 * NOT also send a Content-Security-Policy, so the two layers never duplicate.
 */

/** Per-request nonce, readable by `getRouter()` through a global hook so shared (client) code never imports node:async_hooks. */
export const nonceStore = new AsyncLocalStorage<string>();
(globalThis as { __novaNonceStore?: AsyncLocalStorage<string> }).__novaNonceStore = nonceStore;

export function createNonce(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Buffer.from(bytes).toString("base64");
}

export function buildContentSecurityPolicy(nonce: string, options: { upgradeInsecure?: boolean } = {}): string {
  const directives = [
    "default-src 'self'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'self'",
    "frame-src 'none'",
    "object-src 'none'",
    "manifest-src 'self'",
    "worker-src 'none'",
    `script-src 'self' 'nonce-${nonce}'`,
    `style-src 'self' 'nonce-${nonce}'`,
    // React renders layout/animation values as style="" attributes; attribute styles cannot execute script.
    "style-src-attr 'unsafe-inline'",
    "font-src 'self'",
    "img-src 'self' data:",
    "connect-src 'self'",
  ];
  if (options.upgradeInsecure) directives.push("upgrade-insecure-requests");
  return directives.join("; ");
}

/** True when the request reached the app over HTTPS (as reported by the trusted nginx edge). */
export function isHttpsRequest(request: Request): boolean {
  return request.headers.get("x-forwarded-proto") === "https" || new URL(request.url).protocol === "https:";
}

/** Returns a copy of the response carrying the application security headers. */
export function withSecurityHeaders(response: Response, nonce: string, request: Request): Response {
  const headers = new Headers(response.headers);
  headers.set("content-security-policy", buildContentSecurityPolicy(nonce, { upgradeInsecure: isHttpsRequest(request) }));
  headers.set("cross-origin-opener-policy", "same-origin");
  // Applied by the app only when nginx has not already supplied the equivalent (single source per header).
  if (!headers.has("x-content-type-options")) headers.set("x-content-type-options", "nosniff");
  if (!headers.has("referrer-policy")) headers.set("referrer-policy", "strict-origin-when-cross-origin");
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}
